package com.badrulamin.University_Management.entity;  import com.fasterxml.jackson.annotation.JsonProperty; import jakarta.persistence.*; import jakarta.validation.constraints.Email; import jakarta.validation.constraints.NotBlank; import jakarta.validation.constraints.Size; import lombok.AllArgsConstructor; import lombok.Getter; import lombok.NoArgsConstructor; import lombok.Setter;  import java.time.LocalDate;  @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Entity @Table(name = "admission_candidates") public class AdmissionCandidate extends BaseEntity {      @NotBlank     @Size(max = 100)     @Column(name = "first_name", nullable = false)     private String firstName;      @NotBlank     @Size(max = 100)     @Column(name = "last_name", nullable = false)     private String lastName;      @NotBlank     @Email     @Column(unique = true, nullable = false)     private String email;      @Size(max = 20)     private String phone;      @Column(name = "date_of_birth")     private LocalDate dateOfBirth;      @Size(max = 20)     private String gender;      @Column(columnDefinition = "TEXT")     private String address;      @NotBlank     @Column(name = "application_number", unique = true, nullable = false)     private String applicationNumber;      @Size(max = 50)     private String status;      @ManyToOne(fetch = FetchType.LAZY)     @JoinColumn(name = "applied_course_id")     private Course appliedCourse;      @JsonProperty("appliedCourseId")     public void setAppliedCourseId(Long id) {         if (id != null) {             this.appliedCourse = new Course();             this.appliedCourse.setId(id);         }     }      @JsonProperty     public Long getAppliedCourseId() {         return this.appliedCourse != null ? this.appliedCourse.getId() : null;     } }